const starsOptions=()=>[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('');
function reviewSummary(review){if(!review)return '';return `<div class="review-details">${reviewDimensions.filter(([key])=>review[key]).map(([key,label])=>`<p>${label}: <strong>${review[key]}/5</strong></p>`).join('')}${review.feedback?`<p><strong>Your experience</strong><span data-no-translate>${safe(review.feedback)}</span></p>`:''}${review.downsides?`<p><strong>What could be better</strong><span data-no-translate>${safe(review.downsides)}</span></p>`:''}${review.recommend?`<p>Would recommend: ${review.recommend==='yes'?'Yes':'No'}</p>`:''}</div>`}
renderOrders=function(){$('#orderCount').textContent=orders.length;$('#orderList').innerHTML=orders.length?orders.map(o=>`<article class="orderrow order-with-chat"><div class="order-main"><div><strong>${safe(o.product)} · ${o.qty} ${safe(unitOf(o))}</strong><p>${safe(o.supplier)} · ${safe(o.fulfilment)}</p><small>Demo #${o.id} · ${safe(o.status)}</small></div><strong>₹${o.total.toLocaleString('en-IN')}</strong></div><div class="order-actions"><button data-chat="${o.id}">Order chat ↗</button>${currentUser?.role==='vendor'&&o.status==='Placed'?`<button data-receive="${o.id}">Mark received</button>`:''}${currentUser?.role==='vendor'&&o.status==='Received'&&!o.rating?`<button data-open-review="${o.id}">Write a review</button>`:''}</div>${o.rating?`<details class="saved-review"><summary>Reviewed · ${o.rating} ★</summary>${reviewSummary(o.review)}</details>`:''}</article>`).join(''):'<p class="muted">Your first restock is a search away. Explore the market to place a demo order.</p>'};
const conversationLayer=document.createElement('div');conversationLayer.innerHTML=`<dialog id="reviewDialog" class="review-dialog"><form id="detailedReviewForm"><button id="closeReview" type="button" class="close" aria-label="Close">×</button><span class="eyebrow">SHARE YOUR EXPERIENCE</span><h2>Review your order</h2><p id="reviewOrderName" class="muted" data-no-translate></p><label>Overall rating<select id="reviewOverall" required><option value="">Choose rating</option>${starsOptions()}</select></label><label>Your experience (optional)<textarea id="reviewFeedback" rows="3" maxlength="1000"></textarea></label><label>What could be better (optional)<textarea id="reviewDownsides" rows="3" maxlength="1000"></textarea></label><details class="review-extra"><summary>More details (optional)</summary><div class="review-ratings">${reviewDimensions.map(([key,label])=>`<label>${label}<select id="review-${key}"><option value="">Skip</option>${starsOptions()}</select></label>`).join('')}</div><label>Would you recommend this wholesaler?<select id="reviewRecommend"><option value="">Skip</option><option value="yes">Yes</option><option value="no">No</option></select></label></details><p class="muted review-note">Only the overall rating is required. All other questions are optional.</p><p id="reviewError" class="auth-error" role="alert"></p><button id="submitDetailedReview" class="primary">Submit review →</button></form></dialog><dialog id="chatDialog" class="chat-dialog"><div class="chat-heading"><button id="closeChat" type="button" class="close" aria-label="Close">×</button><span class="eyebrow">PRIVATE ORDER CONVERSATION</span><h2 id="chatOrderTitle" data-no-translate></h2><p id="chatPeer" class="muted" data-no-translate></p></div><p id="chatWaiting" class="chat-waiting" hidden>The wholesaler has not joined yet. Your messages will be saved.</p><div id="chatMessages" class="chat-messages" role="log" aria-live="polite" aria-label="Order messages"></div><p id="chatError" class="auth-error" role="alert"></p><form id="chatForm" class="chat-compose"><label class="visually-hidden" for="chatText">Message</label><textarea id="chatText" rows="2" maxlength="1500" required placeholder="Ask about stock, delivery or pickup"></textarea><button id="sendChat" class="primary">Send →</button></form><p class="chat-note">New messages appear automatically while this conversation is open.</p></dialog>`;document.body.append(conversationLayer);
let reviewingOrder=null,chatState=null,chatTimer=null;
function openReview(id){const order=orders.find(o=>o.id===id);if(!order||order.rating||order.status!=='Received'||currentUser?.role!=='vendor')return;reviewingOrder=id;$('#detailedReviewForm').reset();$('#reviewOrderName').textContent=order.product+' · '+order.supplier;$('#reviewError').textContent='';$('#reviewDialog').showModal();translateUI()}
$('#closeReview').onclick=()=>$('#reviewDialog').close();
$('#detailedReviewForm').onsubmit=async e=>{e.preventDefault();const button=$('#submitDetailedReview');button.disabled=true;$('#reviewError').textContent='';try{const data={rating:Number($('#reviewOverall').value),feedback:$('#reviewFeedback').value,downsides:$('#reviewDownsides').value,recommend:$('#reviewRecommend').value};for(const [key]of reviewDimensions)data[key]=$('#review-'+key).value?Number($('#review-'+key).value):null;await api(`/orders/${reviewingOrder}/review`,{method:'POST',body:JSON.stringify(data)});$('#reviewDialog').close();await Promise.all([refreshOrders(),refreshMarket()]);toast('Your review was saved.')}catch(error){$('#reviewError').textContent=error.message;translateUI()}finally{button.disabled=false}};
function stopChat(){clearInterval(chatTimer);chatTimer=null;chatState=null}
function drawMessages(state){const box=$('#chatMessages'),nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<100;box.innerHTML=state.items.length?state.items.map(m=>`<div class="chat-bubble ${m.senderId===currentUser?.id?'mine':''}"><small data-no-translate>${safe(m.senderName)} · ${safe(new Date(m.createdAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))}</small><p data-no-translate>${safe(m.text)}</p></div>`).join(''):'<p class="muted">Start a conversation about your order.</p>';if(nearBottom||!state.loaded)box.scrollTop=box.scrollHeight;translateUI()}
async function pollMessages(){const state=chatState;if(!state||state.loading||document.hidden||!currentUser)return;state.loading=true;try{const data=await api(`/orders/${state.id}/messages${state.loaded?'?after='+state.cursor:''}`);if(chatState!==state)return;$('#chatPeer').textContent=data.peer;$('#chatWaiting').hidden=data.peerConnected;const items=new Map(state.items.map(m=>[m.id,m]));let changed=false;for(const m of data.messages){if(!items.has(m.id))changed=true;items.set(m.id,m);state.cursor=Math.max(state.cursor,m.id)}state.items=[...items.values()].sort((a,b)=>a.id-b.id);$('#chatError').textContent='';if(changed||!state.loaded)drawMessages(state);state.loaded=true}catch(error){if(chatState===state){$('#chatError').textContent=error.message;if([401,403,404].includes(error.status)){clearInterval(chatTimer);$('#sendChat').disabled=true}translateUI()}}finally{state.loading=false}}
async function openChat(id){const order=orders.find(o=>o.id===id);if(!order)return;stopChat();chatState={id,items:[],cursor:0,loaded:false,loading:false};$('#chatOrderTitle').textContent=order.product+' · #'+id;$('#chatPeer').textContent=order.supplier;$('#chatError').textContent='';$('#chatMessages').innerHTML='';$('#chatText').value='';$('#sendChat').disabled=false;$('#chatWaiting').hidden=true;$('#chatDialog').showModal();const openedState=chatState;await pollMessages();if(chatState===openedState)chatTimer=setInterval(pollMessages,4000)}
$('#closeChat').onclick=()=>$('#chatDialog').close();$('#chatDialog').addEventListener('close',stopChat);
$('#chatForm').onsubmit=async e=>{e.preventDefault();const state=chatState,text=$('#chatText').value.trim();if(!state||!text)return;const button=$('#sendChat');button.disabled=true;try{const {message}=await api(`/orders/${state.id}/messages`,{method:'POST',body:JSON.stringify({text})});if(chatState!==state)return;state.items=[...new Map([...state.items,message].map(m=>[m.id,m])).values()].sort((a,b)=>a.id-b.id);$('#chatText').value='';drawMessages(state);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;await pollMessages()}catch(error){$('#chatError').textContent=error.message;translateUI()}finally{button.disabled=false}};
const previousOrderClick=$('#orderList').onclick;$('#orderList').onclick=e=>{const chat=e.target.closest('[data-chat]'),review=e.target.closest('[data-open-review]');if(chat)return openChat(Number(chat.dataset.chat));if(review)return openReview(Number(review.dataset.openReview));return previousOrderClick(e)};
const previousLogout=$('#logout').onclick;$('#logout').onclick=async()=>{$('#chatDialog').close();$('#reviewDialog').close();stopChat();return previousLogout()};renderOrders();translateUI();

